// CloserOption configures a contract run.
type CloserOption func(*closerConfig)

// CloserSubject declares an implementation to hold to the contract.
//
// Repeat it for every implementation that claims to satisfy the interface — an
// in-memory one, the one backed by a database, the one behind a network. Every
// check and every option is stated once and runs against all of them, which is
// what a conformance suite is for.
func CloserSubject(name string, factory func() idempotentclose.Closer) CloserOption {
	return func(c *closerConfig) {
		c.subjects = append(c.subjects, namedCloserSubject{name, factory})
	}
}

// CloserWithoutDouble declines the second run through CloserStub.
//
// The double run proves the stand-in is faithful, and costs a second pass over
// every check. Decline it where the double is not used.
func CloserWithoutDouble() CloserOption {
	return func(c *closerConfig) { c.withoutDouble = true }
}

// CloserWithClock supplies the clock every time-reading check measures on.
//
// Defaults to the real one, so an implementation that does not take a clock
